#!/bin/bash
# 资产运营中心 - 数据库初始化脚本
# 仅用于维护已有数据库；全新数据库已经由 0001_initial.sql 完整初始化
set -e
DATABASE_URL="${DATABASE_URL:-postgres://kairos_platform:kairos_platform@localhost:5432/kairos_platform}"

echo "=== 创建扫模块表 ==="
psql "$DATABASE_URL" << 'SQL'
CREATE TABLE IF NOT EXISTS scan_assets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL, ip VARCHAR(50) NOT NULL, zone VARCHAR(50) DEFAULT 'Internet', os VARCHAR(100), device_type VARCHAR(50), owner VARCHAR(100), contact_person VARCHAR(50), contact_phone VARCHAR(30), weight INTEGER DEFAULT 50, labels TEXT, last_scanned TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_tasks (id VARCHAR(50) PRIMARY KEY, name VARCHAR(200) NOT NULL, target TEXT NOT NULL, status VARCHAR(20) DEFAULT 'pending', port_policy VARCHAR(20) DEFAULT 'TOP100', domain_brute BOOLEAN DEFAULT false, service_detection BOOLEAN DEFAULT true, os_detection BOOLEAN DEFAULT false, site_identify BOOLEAN DEFAULT false, found_assets INTEGER DEFAULT 0, found_risks INTEGER DEFAULT 0, start_time TIMESTAMPTZ, end_time TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_scanners (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100) NOT NULL, scanner_type VARCHAR(50) DEFAULT 'basic_tcp', enabled BOOLEAN DEFAULT true, config JSONB DEFAULT '{}', created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_machine_rooms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_name VARCHAR(100) NOT NULL, room_code VARCHAR(50) NOT NULL, facility_type VARCHAR(50) DEFAULT '', address VARCHAR(255) DEFAULT '', provider_id BIGINT DEFAULT 0, room_type VARCHAR(50) DEFAULT '', contact_person VARCHAR(50) DEFAULT '', contact_phone VARCHAR(30) DEFAULT '', floor VARCHAR(50), cabinet_count INTEGER DEFAULT 0, area_size VARCHAR(50), remarks TEXT, status VARCHAR(20) DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_service_providers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, provider_name VARCHAR(100) NOT NULL, provider_code VARCHAR(50) NOT NULL, short_name VARCHAR(50) DEFAULT '', logo_url VARCHAR(255), contact_person VARCHAR(50) DEFAULT '', contact_phone VARCHAR(30) DEFAULT '', contact_email VARCHAR(100) DEFAULT '', headquarters VARCHAR(100) DEFAULT '', service_area VARCHAR(100) DEFAULT '', business_license VARCHAR(100) DEFAULT '', remarks TEXT, status VARCHAR(20) DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_security_products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, category VARCHAR(50) DEFAULT '', vendor VARCHAR(100) DEFAULT '', model VARCHAR(100) DEFAULT '', version VARCHAR(50) DEFAULT '', serial_number VARCHAR(100), license_type VARCHAR(50) DEFAULT '', license_expiry TIMESTAMPTZ, management_ip VARCHAR(50), deployment_mode VARCHAR(50) DEFAULT '', cloud_platform_id BIGINT, machine_room_id BIGINT, provider_id BIGINT, status VARCHAR(20) DEFAULT 'active', features TEXT, throughput VARCHAR(50), contact_person VARCHAR(50) DEFAULT '', contact_phone VARCHAR(30) DEFAULT '', remarks TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_cloud_zones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, zone_name VARCHAR(100) NOT NULL, zone_code VARCHAR(50) NOT NULL, description TEXT, created_at TIMESTAMPTZ DEFAULT now(), deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_cloud_platforms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, zone_id BIGINT NOT NULL, platform_name VARCHAR(100) NOT NULL, platform_code VARCHAR(50) NOT NULL, description TEXT, created_at TIMESTAMPTZ DEFAULT now(), deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_cloud_provider_configs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, zone_id BIGINT, platform_id BIGINT, provider VARCHAR(50) NOT NULL, region_id VARCHAR(255) NOT NULL, region_name VARCHAR(100) NOT NULL, available_zones TEXT, account_name VARCHAR(100) NOT NULL, access_key_id VARCHAR(255) DEFAULT '', access_key_secret VARCHAR(255) DEFAULT '', status VARCHAR(20) DEFAULT 'active', remarks TEXT, last_test_time TIMESTAMPTZ, last_test_result TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_resource_tickets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, resource_type VARCHAR(20) DEFAULT 'cloud', ecs_name VARCHAR(200) NOT NULL, ticket_status VARCHAR(30) DEFAULT 'pending_approval', provider_id BIGINT, cloud_platform_id BIGINT, machine_room_id BIGINT, cloud_region VARCHAR(100), cloud_category VARCHAR(100), zone_name VARCHAR(100), rack_units INTEGER DEFAULT 0, customer_name VARCHAR(100), ecs_type VARCHAR(50), ecs_os VARCHAR(50), resource_count INTEGER DEFAULT 1, cpu_cores INTEGER DEFAULT 0, memory_gb INTEGER DEFAULT 0, system_disk VARCHAR(50), system_disk_size_gb INTEGER DEFAULT 0, has_security_product BOOLEAN DEFAULT false, ip_address VARCHAR(50), remarks TEXT, created_by VARCHAR(64) DEFAULT '', approver VARCHAR(100), approve_time TIMESTAMPTZ, approve_comment TEXT, provisioner VARCHAR(100), provision_time TIMESTAMPTZ, provision_details TEXT, deliverer VARCHAR(100), deliver_time TIMESTAMPTZ, deliver_comment TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_business_resources (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, resource_type VARCHAR(20) DEFAULT 'cloud', ecs_name VARCHAR(200) NOT NULL, ecs_status VARCHAR(50) DEFAULT '运行中', resource_id VARCHAR(100) DEFAULT '', cloud_region VARCHAR(100) DEFAULT '', cloud_category VARCHAR(100) DEFAULT '', customer_name VARCHAR(100) DEFAULT '', instance_id VARCHAR(100) DEFAULT '', ecs_type VARCHAR(50) DEFAULT '', ecs_os VARCHAR(50) DEFAULT '', cpu_cores INTEGER DEFAULT 0, memory_gb INTEGER DEFAULT 0, system_disk VARCHAR(50) DEFAULT '', system_disk_size_gb INTEGER DEFAULT 0, has_security_product BOOLEAN DEFAULT false, ip_address VARCHAR(50) DEFAULT '', application_status VARCHAR(30) DEFAULT '待审核', delivery_status VARCHAR(30) DEFAULT '待交付', remarks TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_business_applications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL, description TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ, deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_risks (id VARCHAR(50) PRIMARY KEY, asset_ip VARCHAR(50) NOT NULL, port INTEGER NOT NULL, severity VARCHAR(20) DEFAULT 'Medium', description TEXT NOT NULL, solution TEXT, status VARCHAR(20) DEFAULT 'open', assigned_to VARCHAR(100), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted SMALLINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS scan_port_details (id VARCHAR(50) PRIMARY KEY, asset_id VARCHAR(50) NOT NULL, ip VARCHAR(50) NOT NULL, port INTEGER NOT NULL, protocol VARCHAR(10) DEFAULT 'TCP', status VARCHAR(20) DEFAULT 'open', service_name VARCHAR(100), system_name VARCHAR(100), middleware VARCHAR(100), department VARCHAR(100), owner VARCHAR(100), is_bound BOOLEAN DEFAULT false, notes TEXT, fingerprint JSONB, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), deleted SMALLINT DEFAULT 0);
SQL

echo "=== 补充缺失序列 ==="
psql "$DATABASE_URL" -c "CREATE SEQUENCE IF NOT EXISTS system_oauth2_refresh_token_seq START 100;" 2>/dev/null
psql "$DATABASE_URL" -c "CREATE SEQUENCE IF NOT EXISTS system_oauth2_access_token_seq START 100;" 2>/dev/null
psql "$DATABASE_URL" -c "CREATE SEQUENCE IF NOT EXISTS system_login_log_seq START 100;" 2>/dev/null
psql "$DATABASE_URL" -c "CREATE SEQUENCE IF NOT EXISTS system_operate_log_seq START 100;" 2>/dev/null

echo "=== 补充 Yudao 完整菜单 ==="
psql "$DATABASE_URL" << 'EOSQL'
DROP TABLE IF EXISTS system_menu CASCADE;
CREATE TABLE system_menu (id bigint NOT NULL, name varchar(50) NOT NULL, permission varchar(100) DEFAULT '' NOT NULL, type smallint NOT NULL, sort integer DEFAULT 0 NOT NULL, parent_id bigint DEFAULT 0 NOT NULL, path varchar(200) DEFAULT '', icon varchar(100) DEFAULT '#', component varchar(255), component_name varchar(255), status smallint DEFAULT 0 NOT NULL, visible boolean DEFAULT true NOT NULL, keep_alive boolean DEFAULT true NOT NULL, always_show boolean DEFAULT true NOT NULL, creator varchar(64) DEFAULT '', create_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL, updater varchar(64) DEFAULT '', update_time timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL, deleted smallint DEFAULT 0 NOT NULL, active_menu_id bigint);
EOSQL
# Load from the canonical initialization snapshot
psql "$DATABASE_URL" -c "\copy system_menu FROM PROGRAM 'grep -A100000 \"COPY public.system_menu\" sql/postgresql/0001_initial.sql | tail -n +2 | head -n -1'" 2>/dev/null

echo "=== 添加扫模块菜单 ==="
psql "$DATABASE_URL" << 'SQL'
